public String readString() throws IOException {
    int len = 0;
    for (int i = 0; i < 4; i++) {
        int b = stream.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        len = (len << 8) | (b & 0xFF);
    }
    if (len < 0) {
        throw new IOException("Negative string length");
    }
    byte[] bytes = new byte[len];
    int pos = 0;
    while (pos < len) {
        int n = stream.read(bytes, pos, len - pos);
        if (n == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        pos += n;
    }
    return new String(bytes, "UTF-8");
