protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    // Map each source vertex to its outgoing edge (assumes one outgoing per vertex in path)
    Map<V, E> edgeMap = new HashMap<>();
    // Count incoming edges for each vertex
    Map<V, Integer> indegree = new HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        edgeMap.put(source, e);
        indegree.put(target, indegree.getOrDefault(target, 0) + 1);
        // Ensure source vertex appears in indegree map
        indegree.putIfAbsent(source, indegree.getOrDefault(source, 0));
    }
    // Find starting vertex (indegree 0). If none, pick any vertex (for cycles)
    V start = null;
    for (Map.Entry<V, Integer> entry : indegree.entrySet()) {
        if (entry.getValue() == 0) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // Cycle: pick arbitrary source vertex from the first edge
        for (E e : tour) {
            start = graph.getEdgeSource(e);
            break;
        }
    }
    // Build ordered list of edges
    List<E> orderedEdges = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (current != null && !visited.contains(edgeMap.get(current))) {
        E e = edgeMap.get(current);
        if (e == null) {
            break;
        }
        if (visited.contains(e)) {
            break;
        }
        orderedEdges.add(e);
        visited.add(e);
        current = graph.getEdgeTarget(e);
        // If we are back to the start in a cycle, stop after adding last edge
        if (current != null && current.equals(start)) {
            break;
        }
    }
    if (orderedEdges.isEmpty()) {
        return null;
    }
    V target = graph.getEdgeTarget(orderedEdges.get(orderedEdges.size() - 1));
    double totalWeight = 0.0;
    for (E e : orderedEdges) {
        totalWeight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, start, target, orderedEdges, totalWeight);
