    // start from any edge
    E startEdge = edgeList.remove(0);
    V current = graph.getEdgeSource(startEdge);
    vertexList.add(current);
    List<E> orderedEdges = new ArrayList<>();
    orderedEdges.add(startEdge);
    // keep traversing while we can find an edge whose source matches the current vertex
    while(!edgeList.isEmpty()){
        boolean found = false;
        for(int i=0;i<edgeList.size();i++){
            E e = edgeList.get(i);
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(current)){
                orderedEdges.add(e);
                current = tgt;
                vertexList.add(current);
                edgeList.remove(i);
                found = true;
                break;
            }
            // For undirected graphs, allow either direction
            if(tgt.equals(current)){
                // reverse the edge by treating target as source
                orderedEdges.add(e);
                current = src;
                vertexList.add(current);
                edgeList.remove(i);
                found = true;
                break;
            }
        }
        if(!found){
            break; // cannot extend further
        }
    }
    V source = vertexList.isEmpty() ? null : vertexList.get(0);
    V target = vertexList.isEmpty() ? null : vertexList.get(vertexList.size()-1);
    return new GraphPathImpl<>(graph, source, target, vertexList, orderedEdges);
